sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?spouse WHERE {
  dbr:Up,_Down,_Fragile dbo:director ?director .
  OPTIONAL { ?director dbp:spouse ?spouse . }
  OPTIONAL {
    ?director dbo:spouse ?spouseAlt .
    FILTER (!BOUND(?spouse))
    BIND(?spouseAlt AS ?spouse)
  }
}
LIMIT 100

